const updateItemStatus = `-- name: UpdateItemStatus :one
UPDATE items
SET status = ?, updated_at = DATETIME('now')
WHERE id = ?
RETURNING id, feed_id, hash, title, url, content, author, comment_url, points, comments_count, published_at, status, fetched_at, created_at, updated_at, last_enriched_at, extract_content, extract_status, extract_retries, extract_date
`

type UpdateItemStatusParams struct {
	Status string `json:"status"`
	ID     int64  `json:"id"`
}

func (q *Queries) UpdateItemStatus(ctx context.Context, arg UpdateItemStatusParams) (Item, error) {
	row := q.db.QueryRowContext(ctx, updateItemStatus, arg.Status, arg.ID)
	var i Item
	err := row.Scan(
		&i.ID,
		&i.FeedID,
		&i.Hash,
		&i.Title,
		&i.Url,
		&i.Content,
		&i.Author,
		&i.CommentUrl,
		&i.Points,
		&i.CommentsCount,
		&i.PublishedAt,
		&i.Status,
		&i.FetchedAt,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.LastEnrichedAt,
		&i.ExtractContent,
		&i.ExtractStatus,
		&i.ExtractRetries,
		&i.ExtractDate,
	)
	return i, err
}

const updateItemURL = `-- name: UpdateItemURL :exec
UPDATE items SET url = ?, updated_at = DATETIME('now') WHERE id = ?
`

type UpdateItemURLParams struct {
	Url string `json:"url"`
	ID  int64  `json:"id"`
}

func (q *Queries) UpdateItemURL(ctx context.Context, arg UpdateItemURLParams) error {
	_, err := q.db.ExecContext(ctx, updateItemURL, arg.Url, arg.ID)
	return err
}
